 button.type='button';button.addEventListener('click',()=>{const selected=available.find(([key])=>key===select.value);if(!selected){notify('Choose a saved profile field first');return;}delete input._draftId;delete input._letterDraftId;input._updateLetterLink?.();input.value=profile[selected[0]];input.dispatchEvent(new Event('input',{bubbles:true}));input.focus();});
