let recaptureFollowing=false;
async function followFormRecapture(task,output){if(recaptureFollowing)throw new Error('A recapture is already being checked');recaptureFollowing=true;try{let result;do{await new Promise(resolve=>setTimeout(resolve,700));result=await api('/api/form/recapture-status',{task_id:task});}while(result.status==='running');sessionStorage.removeItem('waypoint-form-recapture');sessionStorage.setItem('waypoint-form-recapture-seen',task);if(result.status!=='complete')throw new Error(result.error||'Recapture needs manual review');const text=result.captured===true?'Page capture saved to the attempt record.':'Page capture remained incomplete.';output.replaceChildren(element('p',text,'review-label'),element('p',result.guidance||'Inspect the live page and saved images. Capture does not prove correctness or submission.','footnote'));if(result.fields_verified!==true||result.attachments_verified!==true||result.page_verified!==true||result.context_current!==true||result.event_saved!==true)output.append(element('p','Some field, attachment, page, context or record checks did not complete; review the session manually.','review-label'));return result;}finally{recaptureFollowing=false;}}
function recaptureControl(sessionId){const box=element('div','','answer-draft'),button=element('button','Capture current page again'),output=element('div');button.type='button';button.addEventListener('click',async()=>{button.disabled=true;output.replaceChildren(element('p','Capturing the current page in the background…','footnote'));try{let pending;try{pending=JSON.parse(sessionStorage.getItem('waypoint-form-recapture')||'null');}catch(_){sessionStorage.removeItem('waypoint-form-recapture');}if(!pending){const active=await api('/api/form/recapture-pending',{});if(active.active)pending={task:active.task_id,session:active.session_id};}if(pending && pending.session!==sessionId)throw new Error('Another review session has a capture pending');if(!pending){const started=await api('/api/form/recapture-start',{session_id:sessionId});pending={task:started.task_id,session:sessionId};}sessionStorage.setItem('waypoint-form-recapture',JSON.stringify(pending));await followFormRecapture(pending.task,output);await recoverReviewSession();}catch(error){if(error.message==='Recapture not found')sessionStorage.removeItem('waypoint-form-recapture');output.replaceChildren(element('p',`Capture needs review: ${error.message}. Use this control again to resume a pending capture.`,'review-label'));}finally{button.disabled=false;}});box.append(button,element('p','Save bounded page segments to the current attempt. The site may change while capturing; manual review remains required.','footnote'),output);return box;}
async function recoverFormRecapture(){let pending;try{pending=JSON.parse(sessionStorage.getItem('waypoint-form-recapture')||'null');}catch(_){sessionStorage.removeItem('waypoint-form-recapture');}try{if(!pending){const active=await api('/api/form/recapture-pending',{});if(active.active)pending={task:active.task_id,session:active.session_id};else if(typeof active.last?.task_id==='string' && active.last.task_id!==sessionStorage.getItem('waypoint-form-recapture-seen'))pending={task:active.last.task_id,session:active.last.session_id};}if(!pending||typeof pending.task!=='string')return;sessionStorage.setItem('waypoint-form-recapture',JSON.stringify(pending));const output=element('div','','answer-draft');document.querySelector('#session-recovery').before(output);output.append(element('p','Recovering a pending page capture…','footnote'));await followFormRecapture(pending.task,output);await recoverReviewSession();}catch(error){if(error.message==='Recapture not found')sessionStorage.removeItem('waypoint-form-recapture');notify(`Could not recover page capture: ${error.message}`);}}
function checkboxEvidenceControl(sessionId,field){const box=element('div','','answer-draft'),button=element('button','Review qualification evidence'),output=element('div');button.type='button';button.addEventListener('click',async()=>{button.disabled=true;output.replaceChildren(element('p','Checking reviewed qualifications locally…','footnote'));try{if(sessionStorage.getItem('waypoint-form-answer'))throw new Error('Finish or recover the pending answer first');const started=await api('/api/form/answer-start',{session_id:sessionId,selector:field.selector});sessionStorage.setItem('waypoint-form-answer',JSON.stringify({task:started.task_id,label:field.label}));let result;do{await new Promise(resolve=>setTimeout(resolve,1000));result=await api('/api/form/answer-status',{task_id:started.task_id});}while(result.status==='running');sessionStorage.removeItem('waypoint-form-answer');if(result.status!=='complete')throw new Error(result.error||'Evidence review failed');const answer=result.answer;output.replaceChildren(element('p',answer.text),element('p','Review the question and every cited qualification. This advice does not select or fill the checkbox.','review-label'));for(const source of Array.isArray(answer.sources)?answer.sources:[])output.append(element('p',`Source: ${source}`,'footnote'));showAnswerEvidence(output,answer);}catch(error){const message=error.message==='The model returned no answer; review this question manually'?'No explanation was returned. This does not establish that you lack the qualification; review the question and your evidence manually.':`Evidence review unavailable: ${error.message}`;output.replaceChildren(element('p',message,'review-label'));}finally{button.disabled=false;}});box.append(button,output);return box;}
function formFieldManualNotice(field,result){const browserHint=result.visible===false?' This browser is hidden; close this review and inspect again with a visible browser to enter it manually. Page changes may not be retained.':'';if(field.sensitive && Array.isArray(result.model_review_selectors) && result.model_review_selectors.includes(field.selector))return `${field.label}: This field needs additional review. Check and answer it in the browser if appropriate.${browserHint}`;if(field.sensitive)return `${field.label}: This field requires manual handling in the browser.${browserHint}`;return `${field.label}: ${field.required?`Needs an answer in the browser.${browserHint}`:'Not mapped'}`;}
function formAllowsFill(result){return Array.isArray(result.manual_review) && !result.manual_review.includes('captcha present') && !result.manual_review.includes('ambiguous form controls need manual review') && !result.manual_review.includes('The application changed during inspection; this view is informational only. Inspect again before filling.');}
function preselectFormSuggestion(selector,repeated){return !Array.isArray(repeated) || !repeated.includes(selector);}
function formRequiresVisibleBrowser(result){return result.visible===false && ((result.fields || []).some(field=>field.sensitive) || (result.manual_review || []).length>0);}
function formMayHavePriorFill(result){return result.fill_attempted!==false;}
