function fitRubricScore(rubric){if(!Array.isArray(rubric)||!rubric.length||rubric.length>12)return null;let total=0,supported=0,unknown=0;for(const item of rubric){const weight=item.importance==='required'?3:item.importance==='preferred'?1:0;if(!weight||!['supported','unknown','contradicted'].includes(item.status))return null;total+=weight;if(item.status==='supported')supported+=weight;else if(item.status==='unknown')unknown+=weight;}const round=(n,d)=>Math.floor((n*100+Math.floor(d/2))/d);return {score:round(supported*2+unknown,total*2),lower:round(supported,total),upper:round(supported+unknown,total)};}
function fitSplitItems(item,first,second){if(typeof item.excerpt!=="string"||typeof first!=="string"||typeof second!=="string")return null;first=first.trim();second=second.trim();if(!first||!second||first===second||!item.excerpt.includes(first)||!item.excerpt.includes(second))return null;const a=item.excerpt.indexOf(first),b=item.excerpt.lastIndexOf(second),c=item.excerpt.indexOf(second),d=item.excerpt.lastIndexOf(first);if(!(a+first.length<=b||c+second.length<=d))return null;return [first,second].map(excerpt=>({...item,excerpt,status:'unknown'}));}
function fitSplitControls(item,update){const box=element('details','','fit-split'),summary=element('summary','Split this criterion for this calculation');box.append(summary,element('p','Enter two separate exact excerpts from this criterion. Each inherits its importance; choose a judgment for each. Closing this section restores the original criterion.','footnote'));const parts=[];for(let i=1;i<=2;i++){const label=element('label',`Part ${i} excerpt`),input=document.createElement('input'),statusLabel=element('label',`Part ${i} judgment`),select=document.createElement('select');input.setAttribute('type','text');input.setAttribute('aria-label',`Part ${i} excerpt for ${item.excerpt}`);input.maxLength=800;select.setAttribute('aria-label',`Part ${i} judgment for ${item.excerpt}`);for(const status of ['unknown','supported','contradicted']){const option=element('option',status);option.value=status;select.append(option);}select.value='unknown';label.append(input);statusLabel.append(select);box.append(label,statusLabel);input.addEventListener('input',update);select.addEventListener('change',update);parts.push({input,select});}box.addEventListener('toggle',update);return {box,items(){if(!box.open)return null;const result=fitSplitItems(item,parts[0].input.value,parts[1].input.value);if(!result)return false;return result.map((part,index)=>({...part,status:parts[index].select.value}));}};}
