function fitInputCoverageNotice(c){if(!c || !['listing_used_chars','listing_total_chars','instructions_used_chars','instructions_total_chars'].every(key=>Number.isSafeInteger(c[key])&&c[key]>=0))return 'Input coverage is unavailable; review the full job and instructions.';if(c.listing_used_chars>c.listing_total_chars||c.instructions_used_chars>c.instructions_total_chars)return 'Input coverage is inconsistent; review the full job and instructions.';if(c.listing_used_chars===c.listing_total_chars&&c.instructions_used_chars===c.instructions_total_chars)return '';const sampling=c.listing_used_chars<c.listing_total_chars&&['beginning_middle_end','evenly_spaced'].includes(c.listing_sampling)?' The job input samples spaced passages from the beginning to the end; text between those passages was omitted.':'';return `Partial inputs: supplied ${c.listing_used_chars} of ${c.listing_total_chars} job characters and ${c.instructions_used_chars} of ${c.instructions_total_chars} instruction characters to the assessment.${sampling} The range does not account for omitted text; review the full sources.`;}
