let duplicateCoverageTimer=null;
function showDuplicateCoverage(coverage,pendingFallback){const node=document.querySelector('#duplicate-index-status');node.hidden=!(coverage?.total || pendingFallback);node.textContent=coverage?.total?`Duplicate comparisons: ${coverage.pending} pending, ${coverage.bounded} limited by comparison bounds, ${coverage.missing_employer} missing usable employer information, of ${coverage.total} jobs.${pendingFallback&&!coverage.pending?' Older cross-employer requisitions are still being rechecked.':''} Matching is heuristic and can miss duplicates.`:pendingFallback?'Checking older jobs for possible duplicates in the background. Review listings carefully while this is incomplete.':'';if((coverage?.pending || pendingFallback)&&duplicateCoverageTimer===null)duplicateCoverageTimer=setTimeout(pollDuplicateCoverage,5000);else if(!coverage?.pending&&!pendingFallback&&duplicateCoverageTimer!==null){clearTimeout(duplicateCoverageTimer);duplicateCoverageTimer=null;}}
async function pollDuplicateCoverage(){duplicateCoverageTimer=null;try{const coverage=await api('/api/duplicate-coverage',{});state.duplicate_coverage=coverage;state.duplicate_index_pending=coverage.index_pending===true || coverage.pending>0;showDuplicateCoverage(coverage,state.duplicate_index_pending);}catch(error){const node=document.querySelector('#duplicate-index-status');node.hidden=false;node.textContent=`Could not refresh duplicate comparison coverage: ${error.message}`;duplicateCoverageTimer=setTimeout(pollDuplicateCoverage,10000);}}
