function renderProfileSummary(profile){const summary=document.querySelector('#profile-summary');summary.replaceChildren();const name=profile.full_name || [profile.first_name,profile.last_name].filter(Boolean).join(' '),location=[profile.city,profile.region,profile.country].filter(Boolean).join(', ');const entries=[['Full name',name],['Preferred name',profile.preferred_name],['Phone',profile.phone],['Location',location],['Email',profile.email],['LinkedIn',profile.linkedin],['Website',profile.website]].filter(([,value])=>typeof value==='string' && value.trim());if(!entries.length)summary.append(element('p','No personal details saved yet. Select Edit to add them.','footnote'));for(const [label,value] of entries){const row=element('div','','profile-summary-row');row.append(element('span',label),element('span',value));summary.append(row);}const preferences=document.querySelector('#preferences-summary');preferences.replaceChildren();for(const [label,value] of [['Remote filter',profile.search_remote_only==='on'?'Remote roles':null],['Allowed locations',profile.search_locations],['Job search',profile.instructions],['Documents',profile.document_instructions]])if(typeof value==='string' && value.trim()){preferences.append(element('strong',label),element('p',value));}if(!preferences.childNodes.length)preferences.append(element('p','No instructions saved yet.','footnote'));}
async function refresh(){const next=await api('/api/state');resetReviewedOrder();state=next;renderProfileSummary(state.profile || {});reconcileJobSelection(selectedJobs,state.jobs);selectionReconciled=true;const reviewEligible=new Set(state.jobs.filter(row=>['shortlisted','prepared'].includes(row.job.state)).map(row=>row.job.id));for(const id of reviewSelectedJobs)if(!reviewEligible.has(id))reviewSelectedJobs.delete(id);updateReviewSelection();const form=document.querySelector('#profile-form');for(const key of ['cv_template_id','cover_template_id']){const select=form.elements[key],old=profileLoaded?select.value:(state.profile[key] || '');select.replaceChildren(new Option('Choose a saved PDF or DOCX',''));for(const doc of state.documents.filter(doc=>/\.(pdf|docx)$/i.test(doc.name)))select.append(new Option(doc.name,doc.id));select.value=old;}if(!profileLoaded){for(const [key,value] of Object.entries(state.profile))if(form.elements[key])form.elements[key].value=value;profileLoaded=true;}renderJobs();renderReviewQueue();const facts=document.querySelector('#facts');facts.replaceChildren();for(const fact of state.facts){facts.append(element('p',fact.text));const split=qualificationSplitControl(fact);if(split)facts.append(split);}const docs=document.querySelector('#documents');docs.replaceChildren();document.querySelector('#document-count').textContent=`Your documents (${state.documents.length})`;if(!state.documents.length)docs.append(element('p','No documents saved yet. Add a file above to get started.','document-empty'));for(const doc of state.documents){const item=element('div','','document-row'),identity=element('div','','document-identity'),fileIcon=element('span','','document-icon'),name=element('div','','document-name'),extension=doc.name.match(/\.([^.]+)$/)?.[1]?.toUpperCase() || 'FILE',button=element('button','Download');fileIcon.textContent=extension.slice(0,4);fileIcon.setAttribute('aria-hidden','true');name.append(element('strong',doc.name),element('small',`${extension} · ${Math.ceil(doc.size/1024)} KiB`));identity.append(fileIcon,name);button.type='button';button.addEventListener('click',async()=>{button.disabled=true;try{const response=await fetch('/api/documents/download',{method:'POST',headers:{'X-Workspace-Token':token,'Content-Type':'application/json'},body:JSON.stringify({id:doc.id})});if(!response.ok){const error=await response.json();throw new Error(error.error || 'Download failed');}const url=URL.createObjectURL(await response.blob());const link=document.createElement('a');link.href=url;link.download=doc.name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){notify(e.message);}finally{button.disabled=false;}});const extract=element('button','Review text');extract.type='button';extract.addEventListener('click',async()=>{let generation=documentReviewGeneration;extract.disabled=true;try{const started=await api('/api/documents/extract-start',{id:doc.id});if(generation===documentReviewGeneration)generation=beginDocumentReview();const result=await followDocumentExtraction(started.task_id);if(generation!==documentReviewGeneration)return;if(result.status!=='complete')throw new Error(result.error || 'Document extraction failed');showDocument({id:started.id,name:started.name,text:result.text,coverage:result.coverage});}catch(e){if(generation===documentReviewGeneration)notify(e.message);}finally{extract.disabled=false;}});item.append(identity,extract,button);if(/\.(pdf|docx)$/i.test(doc.name)){const ats=element('button','Check CV against job');ats.type='button';ats.addEventListener('click',()=>showAtsCheck(doc));item.append(ats);}if(/\.pdf$/i.test(doc.name)){const visual=element('button','Review PDF visually');visual.type='button';visual.addEventListener('click',()=>showDocumentVisual(doc));item.append(visual);const preview=element('button','Preview PDF');preview.type='button';preview.addEventListener('click',()=>previewPdf(doc));item.append(preview);}if(/\.(docx|txt|md|png|jpe?g)$/i.test(doc.name)){const convert=element('button','Convert to PDF');convert.type='button';convert.addEventListener('click',async()=>{if(sessionStorage.getItem('waypoint-conversion')){notify('Resume the pending PDF conversion first.');return;}convert.disabled=true;notify(/\.md$/i.test(doc.name)?'Converting Markdown as plain text; this can take up to 60 seconds':'Converting locally; this can take up to 60 seconds');try{const started=await api('/api/documents/convert-pdf-start',{id:doc.id});sessionStorage.setItem('waypoint-conversion',started.task_id);updateConversionControl();await followConversion(started.task_id);}catch(e){conversionError(e);}finally{convert.disabled=false;}});item.append(convert);}docs.append(item);}document.querySelector('#sealing').textContent=state.sealing;scheduleAutomaticFit();}
