function saveFitBatch(){if(fitBatch)sessionStorage.setItem('waypoint-fit-batch',JSON.stringify(fitBatch));else sessionStorage.removeItem('waypoint-fit-batch');}
function renderFitBatch(){const status=document.querySelector('#fit-batch-status'),stop=document.querySelector('#stop-fit-batch');if(!fitBatch){stop.hidden=true;updateSelection();return;}stop.hidden=false;stop.disabled=fitBatch.stop && fitBatchRunning;status.textContent=`AI assessments: ${fitBatch.index} of ${fitBatch.ids.length} completed${fitBatch.failed ? ` · ${fitBatch.failed} could not be assessed` : ''}${fitBatch.stop ? ' · stopping after the current job' : ''}.`;updateSelection();}
function scheduleAutomaticFit(){if(autoFitRunning){autoFitRescan=true;return;}if(!autoFitPaused)void runAutomaticFit();}
function automaticFitFailureText(id,result,jobs){const title=jobs.find(row=>row?.job?.id===id)?.job?.title || 'Listing',reason=typeof result?.error==='string' && result.error.trim()?result.error:'Assessment could not be saved';return `${Array.from(title).slice(0,100).join('')}: ${Array.from(reason).slice(0,240).join('')}`;}
async function runAutomaticFit(){
 if(autoFitRunning || autoFitPaused)return;
 let pending;try{pending=JSON.parse(sessionStorage.getItem('waypoint-auto-fit')||'null');}catch(_){sessionStorage.removeItem('waypoint-auto-fit');}
 const hasPending=Boolean(pending?.task && pending?.job);
 const intent=sessionStorage.getItem('waypoint-auto-fit-intent');
 if(state.profile?.auto_assess_ai==='off' && !hasPending && !intent){document.querySelector('#auto-fit-status').textContent='Automatic estimates are off.';document.querySelector('#auto-fit-retry').hidden=true;return;}
 if(!hasPending && !intent && !state.facts?.some(f=>!f.requires_review) && !state.profile?.instructions?.trim())return;
 if(fitBatch || sessionStorage.getItem('waypoint-single-fit'))return;
 const status=document.querySelector('#auto-fit-status'),retry=document.querySelector('#auto-fit-retry');
 const basis=JSON.stringify([state.facts.filter(f=>!f.requires_review).map(f=>f.text),state.profile?.instructions||'']);if(basis!==autoFitBasis){autoFitBasis=basis;autoFitAttempted.clear();}
 autoFitRunning=true;updateSelection();let failed=0;const failureDetails=[];
 try{
  if(!hasPending && intent){const current=await api('/api/fit/pending',{});if(current.active && current.job_id===intent){pending={job:intent,task:current.task_id};sessionStorage.setItem('waypoint-auto-fit',JSON.stringify(pending));}sessionStorage.removeItem('waypoint-auto-fit-intent');}
  if(pending?.task && pending?.job){let result;do{await new Promise(resolve=>setTimeout(resolve,1000));result=await api('/api/fit/status',{task_id:pending.task});}while(result.status==='running');sessionStorage.removeItem('waypoint-auto-fit');if(result.status==='complete' && result.saved){showAutomaticFit(pending.job,result);}else{autoFitAttempted.add(pending.job);failed++;if(failureDetails.length<3)failureDetails.push(automaticFitFailureText(pending.job,result,state.jobs));}}
  const ids=state.jobs.filter(row=>['discovered','shortlisted','prepared'].includes(row.job.state)).map(row=>row.job.id);
  for(let offset=0;offset<ids.length;offset+=20){
   if(state.profile?.auto_assess_ai==='off' || fitBatch || sessionStorage.getItem('waypoint-single-fit'))break;
   const slice=ids.slice(offset,offset+20).filter(id=>!autoFitAttempted.has(id));if(!slice.length)continue;
   const items=(await api('/api/fit/batch',{ids:slice})).results;
   for(const item of items){
    if(state.profile?.auto_assess_ai==='off' || fitBatch || sessionStorage.getItem('waypoint-single-fit'))break;
    if(!['missing','stale'].includes(item.status)){if(item.status!=='current')failed++;continue;}
    const current=await api('/api/fit/pending',{});
    if(current.active){autoFitPaused=true;retry.hidden=false;status.textContent='Automatic estimates are waiting for another assessment. Collect or discard it, then retry.';return;}
    if(state.profile?.auto_assess_ai==='off' || fitBatch || sessionStorage.getItem('waypoint-single-fit'))break;
    status.textContent='Estimating job matches locally, one at a time…';
    sessionStorage.setItem('waypoint-auto-fit-intent',item.id);
    const started=await api('/api/fit/start',{id:item.id});
    sessionStorage.setItem('waypoint-auto-fit',JSON.stringify({job:item.id,task:started.task_id}));
    sessionStorage.removeItem('waypoint-auto-fit-intent');
    let result;do{await new Promise(resolve=>setTimeout(resolve,1000));result=await api('/api/fit/status',{task_id:started.task_id});}while(result.status==='running');
    sessionStorage.removeItem('waypoint-auto-fit');
    if(result.status==='complete' && result.saved){showAutomaticFit(item.id,result);}else{autoFitAttempted.add(item.id);failed++;if(failureDetails.length<3)failureDetails.push(automaticFitFailureText(item.id,result,state.jobs));}
   }
  }
  status.textContent=state.profile?.auto_assess_ai==='off'?'Automatic estimates are off.':failed?`Automatic estimates finished; ${failed} jobs need attention.${failureDetails.length?' '+failureDetails.join(' | '):''}${failed>failureDetails.length?' Additional details unavailable.':''}`:'Automatic match estimates are up to date for available jobs.';retry.hidden=!failed;if(failed)autoFitPaused=true;
 }catch(error){if(error.message==='Assessment not found')sessionStorage.removeItem('waypoint-auto-fit');autoFitPaused=true;status.textContent=`Automatic estimates paused: ${error.message}`;retry.hidden=false;}
 finally{autoFitRunning=false;updateSelection();const rescan=autoFitRescan;autoFitRescan=false;if(rescan)scheduleAutomaticFit();}
}
document.querySelector('#auto-fit-retry').addEventListener('click',()=>{autoFitPaused=false;autoFitAttempted.clear();scheduleAutomaticFit();});
async function runFitBatch(){if(!fitBatch || fitBatchRunning)return;fitBatchRunning=true;let failure=null;renderFitBatch();try{while(fitBatch && fitBatch.index<fitBatch.ids.length){if(fitBatch.stop && !fitBatch.task)break;const id=fitBatch.ids[fitBatch.index];if(!fitBatch.task){const current=await api('/api/fit/pending',{});if(current.active && current.job_id!==id){const job=state.jobs.find(item=>item.job.id===current.job_id)?.job;throw new Error(`Resume the pending assessment for ${job?.title || 'the other job'} first.`);}if(current.active){fitBatch.task=current.task_id;}else{const started=await api('/api/fit/start',{id});fitBatch.task=started.task_id;}saveFitBatch();}let result;do{await new Promise(resolve=>setTimeout(resolve,1000));result=await api('/api/fit/status',{task_id:fitBatch.task});}while(result.status==='running');if(result.status!=='complete' || !result.saved)fitBatch.failed++;fitBatch.index++;fitBatch.task=null;saveFitBatch();renderFitBatch();await refresh();}const stopped=fitBatch.stop,done=fitBatch.index,total=fitBatch.ids.length,failed=fitBatch.failed;fitBatch=null;saveFitBatch();document.querySelector('#fit-batch-status').textContent=`AI assessments ${stopped?'stopped':'finished'}: ${done} of ${total}; ${failed} need attention or could not be saved.`;}catch(e){if(fitBatch && fitBatch.task && e.message==='Assessment not found'){fitBatch.task=null;saveFitBatch();}failure=`Assessment paused: ${e.message}. Use Resume assessments to retry.`;}finally{fitBatchRunning=false;renderFitBatch();if(failure)document.querySelector('#fit-batch-status').textContent=failure;document.querySelector('#assess-selected').textContent=fitBatch?'Resume assessments':'Assess selected with local AI';updateSelection();if(!fitBatch)scheduleAutomaticFit();}}
document.querySelector('#assess-selected').addEventListener('click',()=>{if(fitBatch){void runFitBatch();return;}if(!selectionReconciled || !selectedJobs.size || selectedJobs.size>FIT_BATCH_LIMIT)return;fitBatch={ids:[...selectedJobs],index:0,failed:0,task:null,stop:false};saveFitBatch();void runFitBatch();});
document.querySelector('#stop-fit-batch').addEventListener('click',async()=>{if(!fitBatch)return;fitBatch.stop=true;saveFitBatch();renderFitBatch();if(!fitBatchRunning && fitBatch.task){try{await api('/api/fit/discard',{task_id:fitBatch.task});fitBatch.task=null;saveFitBatch();}catch(error){document.querySelector('#fit-batch-status').textContent=`Cannot discard the current assessment: ${error.message}. Resume to collect it.`;return;}}if(!fitBatchRunning)void runFitBatch();});
try{const pending=JSON.parse(sessionStorage.getItem('waypoint-fit-batch') || 'null');if(pending && Array.isArray(pending.ids) && pending.ids.length>0 && pending.ids.length<=FIT_BATCH_LIMIT && Number.isInteger(pending.index) && pending.index>=0 && pending.index<=pending.ids.length && Number.isInteger(pending.failed)){fitBatch=pending;void runFitBatch();}else sessionStorage.removeItem('waypoint-fit-batch');}catch(_){sessionStorage.removeItem('waypoint-fit-batch');}
