function renderSearchPlan(queries,inputDigest,omittedPrivate,omittedInvalid,coverage){const box=document.querySelector('#search-phrases');box.replaceChildren(element('p','Review each phrase before searching: the model can invent specialties or seniority, omit work-arrangement preferences, or include personal details. Some phrases may be broad; check each listing against your requirements. Edit or discard unsuitable phrases.'));if(coverage && (coverage.oversized || coverage.over_limit || coverage.instructions_total_chars>coverage.instructions_used_chars))box.append(element('p',`Planning used ${coverage.included} of ${coverage.reviewed_total} reviewed qualifications; ${coverage.oversized} were too long and ${coverage.over_limit} exceeded the inventory limit.${coverage.instructions_total_chars>coverage.instructions_used_chars?' Some search preferences were not included.':''} Review and adjust the phrases.`,'review-label'));if(Number.isSafeInteger(omittedPrivate)&&omittedPrivate>0)box.append(element('p',`${omittedPrivate} suggested ${omittedPrivate===1?'phrase was':'phrases were'} omitted due to known personal identifiers. Check every remaining phrase; this check is not exhaustive.`,'review-label'));if(Number.isSafeInteger(omittedInvalid)&&omittedInvalid>0)box.append(element('p',`${omittedInvalid} unusable model ${omittedInvalid===1?'suggestion was':'suggestions were'} omitted.`,'review-label'));const seenTerms=new Set();for(const query of queries){const row=element('div','','search-phrase');row.append(element('span',query));const key=query.trim().toLowerCase().split(/\s+/).sort().join(' ');if(seenTerms.has(key))row.append(element('p','Same terms as an earlier phrase; search engines may still treat the order differently.','footnote'));seenTerms.add(key);for(const [label,selector] of [['Use on Jobicy','#jobicy-search input[name=keyword]'],['Use on web','#web-search input[name=query]']]){const choice=element('button',label);choice.type='button';if(label==='Use on Jobicy' && query.length>50){choice.disabled=true;choice.title='Jobicy accepts up to 50 characters; edit this phrase before using it there.';row.append(element('p','Jobicy accepts up to 50 characters; shorten this phrase to search there.','footnote'));}choice.addEventListener('click',async()=>{choice.disabled=true;try{const result=await api('/api/search-plan/current',{input_digest:inputDigest});if(!result.current){sessionStorage.removeItem('waypoint-search-plan');box.replaceChildren(element('p','Profile, qualifications or search instructions changed; generate new phrases.','review-label'));return;}const field=document.querySelector(selector);const details=field.closest('details.manual-job');if(details)details.open=true;field.value=query;field.dataset.planDigest=inputDigest;field.dataset.planQuery=query;field.focus();}catch(error){notify(`Could not verify search phrases: ${error.message}`);}finally{choice.disabled=false;}});row.append(choice);}const add=element('button','Add to web batch');add.type='button';add.addEventListener('click',()=>appendSearchPlanToWebBatch(query,inputDigest,box,add));row.append(add);box.append(row);}}
async function appendSearchPlanToWebBatch(query,digest,box,button){button.disabled=true;try{const current=await api('/api/search-plan/current',{input_digest:digest});if(!current.current){sessionStorage.removeItem('waypoint-search-plan');box.replaceChildren(element('p','Profile, qualifications or search instructions changed; generate new phrases.','review-label'));return;}const field=document.querySelector('#web-search-batch textarea[name=queries]');const binding=searchPlanBinding(field);if(binding && binding!==digest)throw new Error('Clear the previous suggested batch before adding phrases from a new plan');const lines=field.value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(lines.some(line=>line.toLowerCase()===query.toLowerCase())){notify('Phrase is already in the web batch');return;}if(lines.length>=10)throw new Error('The web batch can contain at most 10 phrases');lines.push(query);field.value=lines.join('\n');field.dataset.planDigest=digest;field.dataset.planQuery=field.value;const details=field.closest('details');if(details)details.open=true;field.focus();notify('Phrase added; review the batch before searching');}catch(error){notify(`Could not add search phrase: ${error.message}`);}finally{button.disabled=false;}}
