function modelCanStart(model){return typeof model?.name==='string' && model.format==='gguf' && !model.name.toLowerCase().includes('cloud') && Number.isSafeInteger(model.disk_bytes) && model.disk_bytes>=1073741824 && model.disk_bytes<=17179869184;}
