async function followModelStart(task){if(modelStartFollowing)return;modelStartFollowing=true;const info=document.querySelector('#model-info');try{let result;do{await new Promise(resolve=>setTimeout(resolve,1500));result=await api('/api/model-start/status',{task_id:task});}while(result.status==='running');sessionStorage.removeItem('waypoint-model-start');if(result.status!=='complete')throw new Error(result.error || 'Model startup failed');const gpu=result.model.reported_vram_bytes,cpu=result.model.reported_cpu_bytes;const allocation=Number.isSafeInteger(gpu)&&Number.isSafeInteger(cpu)?` ${ (gpu/1073741824).toFixed(2) } GiB reported on GPU, ${ (cpu/1073741824).toFixed(2) } GiB estimated model offload.`:'';info.textContent=`${result.model.already_running?'Model already running':'Model started'}: ${result.model.model}.${allocation} Checking local status gives a fresh snapshot.`;}catch(error){if(error.message==='Model startup not found')sessionStorage.removeItem('waypoint-model-start');info.textContent=`${error.message}. Check local model status before retrying.`;}finally{modelStartFollowing=false;}}
