document.querySelector('#model-inventory').addEventListener('click',async()=>{const button=document.querySelector('#model-inventory'),panel=document.querySelector('#model-inventory-info');button.disabled=true;panel.replaceChildren(element('p','Checking installed models…'));try{const data=await api('/api/model-inventory');panel.replaceChildren(element('p',`Showing ${data.models.length} valid model(s) from ${data.reported_count} reported; ${data.invalid} invalid ${data.invalid===1?'entry was':'entries were'} omitted${data.examined<data.reported_count?'; inventory capped at 100':''}. Disk size does not establish GPU memory use or readiness.`,'footnote'));const list=document.createElement('ul');list.tabIndex=0;list.setAttribute('aria-label','Installed local models');for(const model of data.models){const item=element('li',`${model.name} · ${Number.isFinite(model.disk_bytes)?(model.disk_bytes/1073741824).toFixed(2)+' GiB on disk':'disk size unavailable'}`),start=element('button','Start model');start.type='button';const supported=modelCanStart(model);start.disabled=!supported;if(!supported)item.append(element('span',' · Startup supports local GGUF models from 1–16 GiB, subject to memory checks.','footnote'));const check=model.memory_check;if(check?.state==='fits_snapshot')item.append(element('p','Current memory snapshot meets the startup estimate, including model size plus 10 GiB of system headroom. Memory is not reserved and model quality is unverified.','footnote'));else if(check?.state==='not_ready')item.append(element('p',`Startup estimate: ${check.reason || 'unavailable'}`,'review-label'));else item.append(element('p','Memory estimate unavailable.','footnote'));start.addEventListener('click',()=>startInstalledModel(model.name,start));item.append(start);list.append(item);}panel.append(list);}catch(error){panel.replaceChildren(element('p',`Could not list installed models: ${error.message}`,'review-label'));}finally{button.disabled=false;}});
function gpuStatusText(result){if(result.state==='unsupported')return 'GPU memory sampling is unavailable on this operating system.';if(result.state==='unavailable'||!Array.isArray(result.adapters)||!result.adapters.length)return 'GPU memory could not be sampled. Model loading must remain manual.';const lines=result.adapters.map((adapter,index)=>{const name=typeof adapter.name==='string'&&adapter.name?adapter.name:`GPU ${index+1}`,gib=value=>Number.isSafeInteger(value)&&value>=0?`${(value/1073741824).toFixed(2)} GiB`:'unavailable';return `${name}: ${gib(adapter.used_bytes)} used / ${gib(adapter.total_bytes)} dedicated`;});return `${lines.join(' · ')}. ${result.state==='sampled'?'':'Some GPU data is incomplete. '}Snapshot only; usage can change and model loading may need additional memory.`;}
