function modelStatusText(result){const messages={no_model:'Ollama is reachable but reports no loaded model.',multiple_models:'Ollama reports multiple loaded models; use one model at a time.',not_fully_gpu:'The loaded model has no GPU allocation or exceeds the system-memory offload limit.',over_budget:'The reported GPU use exceeds the 16 GiB limit.',incomplete_report:'Ollama did not provide enough information to verify the model.',unreachable:'Ollama could not be reached on this PC.'};if(!result.model)return `${messages[result.state] || 'No eligible model is available.'} ${result.error || ''}`.trim();const context=Number.isSafeInteger(result.context_length)&&result.context_length>0?`${result.context_length} token context`:'context unavailable';const vision=result.vision===true?'Vision reported':result.vision===false?'Vision not reported; visual inspection needs a vision model':'Vision capability could not be confirmed';return `Ready: ${result.model} · ${((result.reported_vram_bytes || 0)/1073741824).toFixed(2)} GiB reported on GPU · ${((result.reported_cpu_bytes || 0)/1073741824).toFixed(2)} GiB estimated model offload · ${context}. ${vision}. Residency and capabilities are snapshots, not proof of accuracy or a memory reservation.`;}
