async function followTemplateEdit(task){let result;do{await new Promise(resolve=>setTimeout(resolve,1000));result=await api('/api/documents/edit-template-status',{task_id:task});}while(result.status==='running');sessionStorage.removeItem('waypoint-template-edit');if(result.status!=='complete'){const error=new Error(result.error || 'Template edit failed');error.terminal=true;throw error;}return result;}
function templateTextCheck(result){if(!result.docx_name)return '';const status=result.text_check?.status,notice=result.text_check?.accepted_revision_view===true?' The PDF uses a temporary accepted view of removed revisions; the saved DOCX keeps its revision history.':'',coverage=pdfExtractionCoverageNotice(result.text_check?.pdf_coverage),setup=result.text_check?.reason_code==='missing_pdf_tools'?' Set up PDF tools in Settings > Local tools and setup, or check the configured Python override, then export again to check its text.':'';return (status==='matches'?'Selectable PDF text matches extracted DOCX text after whitespace normalization. This does not verify layout or all content.':status==='differs'?'Selectable PDF text differs from extracted DOCX text; inspect both documents carefully.':'Selectable PDF text could not be compared with the DOCX; inspect both documents carefully.')+(coverage?` ${coverage}`:'')+notice+setup;}
async function followTemplateSuggestion(task){let failures=0;for(let attempts=0;attempts<1200;attempts++){await new Promise(resolve=>setTimeout(resolve,1000));try{const result=await api('/api/documents/template-suggest-status',{task_id:task});failures=0;if(result.status!=='running')return result;}catch(error){if(++failures>=3)throw error;}}throw new Error('Suggestion is still running; try again later');}
function showTemplateSuggestionReview(container,suggestion,original){if(suggestion.cosmetic_retry==='revised')container.append(element('p','A second drafting attempt produced this alternative; review its wording and evidence.','review-label'));else if(['failed','needs_review','unchanged'].includes(suggestion.cosmetic_retry))container.append(element('p','A second drafting attempt did not produce an accepted alternative; the first suggestion is shown.','review-label'));if(suggestion.text===original)container.append(element('p','The model returned the original passage unchanged. You can edit it manually or try different writing instructions.','review-label'));else if(typeof suggestion.text==='string'&&typeof original==='string'&&suggestion.text.replaceAll('’',"'").replace(/\s+/gu,' ').trim()===original.replaceAll('’',"'").replace(/\s+/gu,' ').trim())container.append(element('p','Only spacing or apostrophe style changed. Review the passage or try different writing instructions.','review-label'));if(suggestion.first_person_opening_changed)container.append(element('p','The suggestion changed whether the passage begins with “I” or “we”. Check its voice and tense; this change may be intentional.','review-label'));if(suggestion.additional_sources_cited){container.append(element('p','The initial or final draft cites qualifications beyond the selected passage. Check whether the suggestion adds information you intended to include.','review-label'));if(Array.isArray(suggestion.initial_draft_sources))for(const source of suggestion.initial_draft_sources)container.append(element('p',`Initial draft source: ${source}`,'footnote'));}container.append(element('p','A supported claim may rely on the selected template passage, which has not been independently verified. Check the original evidence.','footnote'));showAnswerEvidence(container,suggestion);}
function batchTemplateSuggestions({text, documentResult, jobSelect, changes, renderQueue, isBusy, setBusy}) {
 const section=element('section','','template-batch-suggestions');
 const button=element('button','Suggest selected lines with local AI');button.type='button';
 const status=element('p','Select up to five complete, unique lines in the extracted text, then choose a job. Review and add each suggestion individually.','footnote');status.setAttribute('role','status');
 const results=element('div');section.append(button,status,results);
 button.addEventListener('click',async()=>{
  if(isBusy()){notify('Finish the current document operation first');return;}
  const job=jobSelect.value, selection=text.value.slice(text.selectionStart,text.selectionEnd);
  const lines=selection.split(/\r?\n/).map(line=>line.trim()).filter(Boolean);
  if(!job || !lines.length || lines.length>5 || lines.length+changes.length>5){notify('Choose a job and select up to five lines within the available queue slots');return;}
  const bytes=new TextEncoder();
  if(lines.some((line,index)=>bytes.encode(line).length>1000 || /[\x00-\x1f\x7f]/.test(line) || text.value.split(line).length!==2 || lines.some((other,i)=>i!==index && (other.includes(line)||line.includes(other))) || changes.some(change=>change.before.includes(line)||line.includes(change.before)))){notify('Each selected line must be unique, non-overlapping, and within the size limit');return;}
  results.replaceChildren();setBusy(true);button.disabled=true;let completed=0;
  try{
   for(const [index,before] of lines.entries()){
    status.textContent=`Drafting passage ${index+1} of ${lines.length} locally…`;
    const started=await api('/api/documents/template-suggest-start',{id:documentResult.id,job_id:job,before});let result;
    result=await followTemplateSuggestion(started.task_id);
    if(result.status!=='complete')throw new Error(result.error || 'Suggestion failed');
    if(result.document_id!==documentResult.id || result.job_id!==job || result.before!==before || typeof result.digest!=='string' || !/^[0-9a-f]{64}$/.test(result.digest) || typeof result.suggestion?.text!=='string' || !Array.isArray(result.suggestion.sources))throw new Error('Suggestion context is unavailable; review manually');
    const card=element('article','','template-batch-item');card.append(element('p',`Original: ${before}`),element('p',`Suggestion: ${result.suggestion.text}`));
    for(const source of result.suggestion.sources)card.append(element('p',`Source: ${source}`,'footnote'));
    showTemplateSuggestionReview(card,result.suggestion,before);
    const add=element('button','Add reviewed suggestion');add.type='button';add.disabled=true;
    add.addEventListener('click',()=>{if(isBusy() || jobSelect.value!==job || changes.length>=5 || changes.some(change=>change.before.includes(before)||before.includes(change.before))){notify('The job or queue changed; review the selection again');return;}changes.push({before,after:result.suggestion.text,suggestion_digest:result.digest,suggestion_job_id:job});add.disabled=true;add.textContent='Added to queue';renderQueue();});
    card.append(add);results.append(card);completed++;
   }
   status.textContent=`${completed} suggestions ready. Review each claim and add only the changes you want.`;
  }catch(error){status.textContent=`Stopped after ${completed} of ${lines.length} passages: ${error.message}. Existing suggestions remain available for review.`;}
  finally{setBusy(false);button.disabled=false;for(const add of results.querySelectorAll('button'))if(add.textContent==='Add reviewed suggestion')add.disabled=false;}
 });
 return section;
}
function documentExtractionCoverageNotice(coverage){if(coverage?.kind==='docx'){const f=coverage.footnote_references,e=coverage.endnote_references,u=coverage.unresolved_note_references;if(!Number.isSafeInteger(f)||f<0||!Number.isSafeInteger(e)||e<0||!Number.isSafeInteger(u)||u<0||u>f+e)return 'DOCX note coverage is unavailable. Review the original document.';if(f+e>0)return `DOCX contains ${f} footnote and ${e} endnote reference(s). ${u?`${u} note reference(s) could not be resolved. `:''}Resolved note text is appended once after the main text; verify reading order and review the original document.`;return null;}return pdfExtractionCoverageNotice(coverage);}
function pdfExtractionCoverageNotice(coverage){if(!coverage || !Array.isArray(coverage.pages_without_selectable_text))return null;const blank=Array.isArray(coverage.structurally_blank_pages)?coverage.structurally_blank_pages:[],unknown=coverage.pages_without_selectable_text.filter(page=>!blank.includes(page));const messages=[];if(unknown.length)messages.push(`No selectable text was found on PDF ${unknown.length===1?'page':'pages'} ${unknown.join(', ')} of ${coverage.pages}. These pages may be blank or scanned; inspect them and use OCR or a text-based copy if needed.`);if(blank.length)messages.push(`PDF ${blank.length===1?'page':'pages'} ${blank.join(', ')} ${blank.length===1?'has':'have'} no page content or annotations and ${blank.length===1?'appears':'appear'} blank.`);const mixed=coverage.pages_with_images_and_text,unchecked=coverage.pages_with_unknown_image_inventory;if(Array.isArray(mixed)&&mixed.length)messages.push(`PDF ${mixed.length===1?'page':'pages'} ${mixed.join(', ')} also ${mixed.length===1?'contains':'contain'} images. These may contain text missing from the extraction; inspect the original page.`);if(Array.isArray(unchecked)&&unchecked.length)messages.push(`Image content could not be checked on PDF ${unchecked.length===1?'page':'pages'} ${unchecked.join(', ')}; inspect the original.`);return messages.length?messages.join(' '):null;}
