async function followDocumentReview(task,progress){let result;do{await new Promise(resolve=>setTimeout(resolve,1500));result=await api('/api/documents/suggest-status',{task_id:task});if(result.status==='running' && progress && result.total_bytes>0)progress.textContent=`Reviewing locally: attempted through byte ${result.presented_bytes} of ${result.total_bytes} across ${result.attempted_sections} ${result.attempted_sections===1?'section':'sections'}; ${result.failed_sections} failed.`;}while(result.status==='running');sessionStorage.removeItem('waypoint-document-review');if(result.status!=='complete')throw new Error(result.error || 'Document review failed');return result;}
function renderDocumentSuggestions(panel,result){const coverageNotice=documentExtractionCoverageNotice(result.coverage);if(coverageNotice)panel.append(element('p',coverageNotice,'review-label'));if(Number.isSafeInteger(result.total_bytes)&&Number.isSafeInteger(result.presented_bytes)){panel.append(element('p',`Attempted through byte ${result.presented_bytes} of ${result.total_bytes} across ${result.attempted_sections} overlapping ${result.attempted_sections===1?'section':'sections'}; ${result.failed_sections} ${result.failed_sections===1?'section':'sections'} failed.`,'footnote'));if(result.truncated)panel.append(element('p','Some document text was not attempted. Review the remaining text manually.','review-label'));if(result.failed_sections)panel.append(element('p','One or more sections could not be reviewed; inspect the document manually.','review-label'));if(result.limited_sections || result.omitted_excerpts)panel.append(element('p',`The model returned at least 12 suggestions in ${result.limited_sections} ${result.limited_sections===1?'section':'sections'}; it may have missed more. ${result.omitted_excerpts} additional distinct excerpts were omitted by the overall limit.`,'review-label'));if(result.rejected_excerpts)panel.append(element('p',`${result.rejected_excerpts} model suggestions were discarded because they were not exact document excerpts. Review the document for missed qualifications.`,'review-label'));if(result.stopped)panel.append(element('p',`Review stopped: ${result.stopped}`,'review-label'));}else if(result.truncated)panel.append(element('p','Only part of the document was reviewed. Inspect the remainder manually.','review-label'));panel.append(element('p','Review each excerpt in context; selecting it attests that it is accurate.'));const options=[];for(const excerpt of result.excerpts){const label=element('label','','field-selection'),box=document.createElement('input');box.type='checkbox';box.value=excerpt;label.append(box,document.createTextNode(` ${excerpt}`));panel.append(label);options.push(box);}if(!options.length){panel.append(element('p','No exact excerpts were suggested.'));return;}const add=element('button','Add selected qualifications');add.type='button';add.addEventListener('click',async()=>{const chosen=options.filter(box=>box.checked&&!box.disabled);if(!chosen.length){notify('Select qualifications to add');return;}add.disabled=true;let added=0;const errors=[];for(const box of chosen){try{await api('/api/facts',{text:box.value});box.checked=false;box.disabled=true;added++;}catch(error){errors.push(error.message);}}await refresh().catch(()=>{});notify(errors.length?`Added ${added}; ${errors.length} failed: ${errors[0]}`:`Added ${added} ${added===1?'qualification':'qualifications'}`);add.disabled=false;});panel.append(add);}
try{const pending=JSON.parse(sessionStorage.getItem('waypoint-document-review') || 'null');if(pending){const panel=document.querySelector('#document-preview');const progress=element('p','Reviewing document locally…','document-review-progress');panel.replaceChildren(element('h3',`Recovering document review: ${pending.name}`),progress);followDocumentReview(pending.task,progress).then(result=>{panel.replaceChildren(element('h3',`Document review: ${pending.name}`));renderDocumentSuggestions(panel,result);}).catch(e=>{if(e.message==='Document review task not found')sessionStorage.removeItem('waypoint-document-review');panel.append(element('p',e.message,'review-label'));});}}catch(_){sessionStorage.removeItem('waypoint-document-review');}


