async function followGmailPassword(id){const info=document.querySelector('#gmail-info'),cancel=document.querySelector('#gmail-password-cancel');cancel.hidden=false;try{let result;do{await new Promise(resolve=>setTimeout(resolve,1000));result=await api('/api/gmail/password-status',{task_id:id});if(result.cancel_requested)info.textContent='Cancellation requested; waiting for the current network operation to finish.';}while(result.status==='running');sessionStorage.removeItem('waypoint-gmail-password');if(result.status!=='complete')throw new Error(result.error || 'Gmail connection failed');await gmailStatus();notify('Gmail authentication succeeded; no email was sent.');}catch(error){if(error.message==='Gmail connection not found')sessionStorage.removeItem('waypoint-gmail-password');info.textContent=error.message;}finally{cancel.hidden=true;cancel.disabled=false;}}
document.querySelector('#gmail-password-cancel').addEventListener('click',async event=>{const button=event.currentTarget,id=sessionStorage.getItem('waypoint-gmail-password');if(!id)return;button.disabled=true;try{await api('/api/gmail/password-cancel',{task_id:id});document.querySelector('#gmail-info').textContent='Cancellation requested; waiting for the current network operation to finish.';}catch(error){document.querySelector('#gmail-info').textContent=error.message;button.disabled=false;}});
document.querySelector('#gmail-password-connect').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button');button.disabled=true;try{const started=await api('/api/gmail/password-start',{email:form.elements.email.value.trim(),password:form.elements.password.value});form.elements.password.value='';sessionStorage.setItem('waypoint-gmail-password',started.task_id);document.querySelector('#gmail-info').textContent='Checking Gmail authentication; no message will be sent.';await followGmailPassword(started.task_id);}catch(error){document.querySelector('#gmail-info').textContent=error.message;}finally{form.elements.password.value='';button.disabled=false;}});
const pendingGmailPassword=sessionStorage.getItem('waypoint-gmail-password');if(pendingGmailPassword)followGmailPassword(pendingGmailPassword);
async function followGmail(id){const info=document.querySelector('#gmail-info'),cancel=document.querySelector('#gmail-cancel');cancel.hidden=false;try{for(;;){const result=await api('/api/gmail/connect-status',{task_id:id});if(result.status==='complete'){sessionStorage.removeItem('waypoint-gmail-connect');await gmailStatus();break;}if(result.status==='failed'){sessionStorage.removeItem('waypoint-gmail-connect');throw new Error(result.error || 'Connection failed');}await new Promise(resolve=>setTimeout(resolve,1000));}}catch(e){info.textContent=e.message;if(e.message==='Gmail connection not found')sessionStorage.removeItem('waypoint-gmail-connect');}finally{cancel.hidden=true;}}
document.querySelector('#gmail-connect').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),file=form.elements.client.files[0];if(!file || file.size>32768){notify('Choose an OAuth JSON file no larger than 32 KiB');return;}button.disabled=true;try{const result=await api('/api/gmail/connect-start',{client_json:await file.text()});sessionStorage.setItem('waypoint-gmail-connect',result.task_id);document.querySelector('#gmail-info').textContent='Complete Google consent in your browser.';await followGmail(result.task_id);}catch(e){notify(e.message);}finally{button.disabled=false;form.reset();}});
