async function storageStatus(){const result=await api('/api/storage/status',{}),form=document.querySelector('#storage-form'),temporary=result.process_override===true;document.querySelector('#storage-info').textContent=temporary?`Active temporary workspace: ${result.active || 'unavailable'}. This process uses a workspace override; restart without it to change the saved folder.`:`Active: ${result.active || 'unavailable'} · Configured: ${result.configured}`;form.elements.path.value=result.configured;form.elements.path.disabled=temporary;form.querySelector('button').disabled=temporary;}
