function updateCandidateSelection(){
 document.querySelector('#candidate-selected-count').textContent=`${selectedCandidates.size} ${selectedCandidates.size===1?'listing':'listings'} selected`;
 document.querySelector('#candidate-batch-start').disabled=!candidateSelectionReady || candidateBatchRunning || (!candidateBatch && (selectedCandidates.size===0 || selectedCandidates.size>100));
 const status=document.querySelector('#candidate-selection-save-status'),retry=document.querySelector('#candidate-save-retry');
 const dirty=candidateSelectionSaved<candidateSelectionRevision;
 if(status)status.textContent=!candidateSelectionReady?'Restoring saved selections…':!candidateSelectionCanSave?'Selection storage is unavailable. Changes are not saved; reload to recover storage.':candidateSelectionSaving?'Saving selections…':dirty?'Selections are not saved. Retry, or note your changes before reloading if another window changed them.':'Selections saved locally.';
 if(retry){retry.hidden=!candidateSelectionReady || !candidateSelectionCanSave || candidateSelectionSaving || !dirty;retry.disabled=retry.hidden;}
 const list=document.querySelector('#selected-candidates-list');if(!list || typeof list.replaceChildren!=='function')return;
 list.replaceChildren();
 if(!selectedCandidates.size){list.append(element('li','No listings selected.','footnote'));return;}
 for(const item of selectedCandidates.values()){
  const row=element('li','','selected-candidate-row'),info=element('span','','selected-candidate-info');
  info.append(element('strong',item.title),element('span',item.url,'footnote'));
  const remove=element('button','Remove');remove.type='button';remove.disabled=!candidateSelectionReady || Boolean(candidateBatch) || candidateBatchRunning;remove.setAttribute('aria-label',`Remove ${item.title} from selected listings`);
  remove.addEventListener('click',()=>{if(candidateBatch || candidateBatchRunning)return;selectedCandidates.delete(item.url);for(const checkbox of document.querySelectorAll('[data-waypoint-candidate]'))if(checkbox.getAttribute('data-waypoint-candidate')===item.url)checkbox.checked=false;queueCandidateSelectionSave();updateCandidateSelection();});
  row.append(info,remove);list.append(row);
 }
}
function sameCandidateSelection(left,right){function contextKey(value){if(value==null)return 'null';if(typeof value!=='object'||!Array.isArray(value.engines)||!Array.isArray(value.alternative_published_dates)||typeof value.published_date!=='string'||typeof value.engines_limited!=='boolean'||typeof value.dates_limited!=='boolean'||!value.engines.every(item=>typeof item==='string')||!value.alternative_published_dates.every(item=>typeof item==='string'))return undefined;if(value.coverage_limited!==undefined&&typeof value.coverage_limited!=='boolean')return undefined;if(value.indexed_date!==undefined&&typeof value.indexed_date!=='string')return undefined;if(value.alternative_indexed_dates!==undefined&&(!Array.isArray(value.alternative_indexed_dates)||!value.alternative_indexed_dates.every(item=>typeof item==='string')))return undefined;if(!value.engines.length&&!value.published_date&&!value.indexed_date&&!(value.alternative_indexed_dates||[]).length&&!value.alternative_published_dates.length&&!value.engines_limited&&!value.dates_limited&&!value.coverage_limited)return 'null';return JSON.stringify([value.engines,value.published_date,value.indexed_date||'',value.alternative_indexed_dates||[],value.alternative_published_dates,value.engines_limited,value.dates_limited,value.coverage_limited===true]);}return Array.isArray(left) && Array.isArray(right) && left.length===right.length && left.every((item,index)=>{const a=contextKey(item?.search_context),b=contextKey(right[index]?.search_context);return a!==undefined && b!==undefined && item?.url===right[index]?.url && item?.title===right[index]?.title && a===b;});}
async function persistCandidateSnapshot(expected,items){for(let attempt=0;attempt<2;attempt++){try{const result=await api('/api/web-search/selection',{action:'save',revision:expected,items});if(!Number.isSafeInteger(result.revision) || result.revision!==expected+1)throw Error('Invalid saved selection revision');return result.revision;}catch(error){let current;try{current=await api('/api/web-search/selection',{action:'load'});}catch(_){throw error;}if(current.revision===expected+1 && sameCandidateSelection(current.items,items))return current.revision;if(current.revision!==expected)throw Error('Selection changed in another window; reload before saving');if(attempt===1)throw error;}}throw Error('Selected listings could not be saved');}
async function saveCandidateSelection(){if(!candidateSelectionReady || !candidateSelectionCanSave || candidateSelectionSaving)return;candidateSelectionSaving=true;updateCandidateSelection();try{while(candidateSelectionSaved<candidateSelectionRevision){const revision=candidateSelectionRevision;candidateSelectionVersion=await persistCandidateSnapshot(candidateSelectionVersion,[...selectedCandidates.values()]);candidateSelectionSaved=revision;}}catch(error){notify(`Selected listings could not be saved: ${error.message}`);}finally{candidateSelectionSaving=false;updateCandidateSelection();}}
