let webSearchFollowing=false;async function followWebSearch(id){if(webSearchFollowing)return;webSearchFollowing=true;try{const panel=document.querySelector('#web-search-results');let result;do{await new Promise(resolve=>setTimeout(resolve,1000));result=await api('/api/web-search/status',{task_id:id});}while(result.status==='running');if(result.status!=='complete'){sessionStorage.removeItem('waypoint-web-search');throw new Error(result.error || 'Web search failed');}const data=result.data;panel.replaceChildren(element('p',`${data.results.length} candidate links · ${searchCoverage(data)}.`));for(const item of data.results)panel.append(webCandidate(item));}finally{webSearchFollowing=false;}}
