function linkRankCoverage(c){if(!c||![c.total,c.examined,c.failed_batches,c.nominated,c.finalists].every(Number.isSafeInteger)||c.total<0||c.examined<0||c.examined>c.total||c.failed_batches<0||c.nominated<0||c.finalists<0||c.finalists>c.nominated)return 'Ranking coverage unavailable; inspect all links manually.';let text=`Local model considered ${c.examined} of ${c.total} displayed links`;if(c.failed_batches)text+=`; ${c.failed_batches} batch failed`;if(c.nominated>c.finalists)text+=`; ${c.nominated-c.finalists} nominated links were omitted from the final comparison`;if(c.global_ranking==='unavailable')text+='; final comparison unavailable';if(c.query_redacted)text+='; URL queries and fragments were omitted from model input';if(c.details_limited)text+='; some link or page details were shortened';return `${text}. Suggestions can be wrong or incomplete; inspect all links manually.`;}
async function recoverLinkRank(){
 if(recoveringLinkRank)return;
 let pending;try{pending=JSON.parse(sessionStorage.getItem('waypoint-link-rank')||'null');}catch(_){sessionStorage.removeItem('waypoint-link-rank');return;}
 if(!pending || typeof pending.task!=='string' || typeof pending.session!=='string'){if(pending)sessionStorage.removeItem('waypoint-link-rank');return;}
 setWorkspaceView('applications');recoveringLinkRank=true;
 const panel=element('div','','notice');panel.setAttribute('aria-live','polite');panel.append(element('p','Recovering local link suggestions…'));document.querySelector('#session-recovery').before(panel);
 try{let result;do{await new Promise(resolve=>setTimeout(resolve,1000));result=await api('/api/form/link-rank-status',{task_id:pending.task});if(result.session_unavailable)panel.firstElementChild.textContent='The review session ended or changed. Waiting for the local ranking to finish before releasing it.';}while(result.status==='running');sessionStorage.removeItem('waypoint-link-rank');if(result.status!=='complete')throw new Error(result.error || 'Link ranking failed');panel.replaceChildren(element('h3','Recovered link suggestions'),element('p','These suggestions describe an earlier page snapshot. Resume the review session and inspect the current page before choosing a link. Nothing was opened.','footnote'));panel.append(element('p',linkRankCoverage(result.coverage),'review-label'));if(!result.links?.length)panel.append(element('p','No likely application links were suggested.'));for(const link of result.links || [])panel.append(element('p',`${link.label || 'Unlabelled link'} · ${link.url}`));}
 catch(error){if(/not found|session expired/i.test(error.message))sessionStorage.removeItem('waypoint-link-rank');panel.replaceChildren(element('p',`Could not recover link suggestions: ${error.message}`,'review-label'));if(sessionStorage.getItem('waypoint-link-rank')){const retry=element('button','Retry recovering link suggestions');retry.type='button';retry.addEventListener('click',()=>{panel.remove();void recoverLinkRank();});panel.append(retry);}}finally{recoveringLinkRank=false;}
}
